import { Command } from "commander";

import { logger } from "./utils/logger";
import { buildInfo } from "./utils/build_info";
import { COMPAT_FORMAT } from "./compat/compatibility";
import { FWU_HOST_PROTOCOLS, FWU_MAX_CHUNK } from "./S1TTXX/fwu/session/wire";
import { WIRE_LOG_VERSIONS } from "./S1TTXX/services/wire_trace";

/**
 * `station-cli capabilities --json` — what this binary can do, generated by
 * walking its own command tree, so it can never claim a command it lacks.
 *
 * Callers probe this instead of comparing version numbers: the kiosk asks
 * whether `fw-apply` exists before offering firmware updates, the firmware
 * contract gates a check on the flag it needs, and the release job publishes
 * the same document in metadata.json (`capabilities`). Fields are only ever
 * added; `format` changes if one is ever removed or renamed.
 */

export const CAPABILITIES_FORMAT = "station-cli-capabilities/v1";

export interface CommandCapability {
  /** Full command path, e.g. `fw-apply` or `config check`. */
  name: string;
  /** Long flags (or the short one when there is no long form), e.g. `--dry-run`. */
  options: string[];
  arguments: string[];
}

export interface Capabilities {
  format: typeof CAPABILITIES_FORMAT;
  name: string;
  version: string;
  /** The release tag this binary was built for, when the build recorded it. */
  tag: string | null;
  commit: string | null;
  /** Options every command accepts (`--raw`, `--no-retry`, …). */
  globalOptions: string[];
  commands: CommandCapability[];
  features: {
    /** The headless firmware-update engine (fw-status / fw-plan / fw-apply). */
    firmwareUpdate: boolean;
    /** Firmware candidates are gated by this compatibility.json format. */
    compatibility: { formats: string[] };
    /** Bootloader FWU protocol versions this CLI speaks (`major.minor`), and its DATA chunk ceiling. */
    fwu: { protocols: string[]; maxChunk: number };
    /** Station pogo-wire log formats `--raw` can decode. */
    wireLog: { versions: number[] };
    /** Credentials accepted as JSON on stdin (`--config-stdin`). */
    configStdin: boolean;
  };
}

function optionNames(cmd: Command): string[] {
  return cmd.options
    .filter((o) => !o.hidden)
    .map((o) => o.long ?? o.short ?? o.flags)
    .filter((n): n is string => !!n);
}

function walk(cmd: Command, prefix: string, out: CommandCapability[]): void {
  for (const sub of cmd.commands) {
    const name = prefix ? `${prefix} ${sub.name()}` : sub.name();
    if (name === "help") continue;
    out.push({
      name,
      options: optionNames(sub),
      arguments: sub.registeredArguments.map((a) => a.name()),
    });
    walk(sub, name, out);
  }
}

export function collectCapabilities(program: Command): Capabilities {
  const commands: CommandCapability[] = [];
  walk(program, "", commands);
  const has = (n: string) => commands.some((c) => c.name === n);
  const info = buildInfo();
  return {
    format: CAPABILITIES_FORMAT,
    name: program.name(),
    version: program.version() ?? "0.0.0",
    tag: info.tag,
    commit: info.commit,
    globalOptions: optionNames(program).filter((n) => n !== "--version"),
    commands,
    features: {
      firmwareUpdate: has("fw-status") && has("fw-plan") && has("fw-apply"),
      compatibility: { formats: [COMPAT_FORMAT] },
      fwu: { protocols: [...FWU_HOST_PROTOCOLS], maxChunk: FWU_MAX_CHUNK },
      wireLog: { versions: [...WIRE_LOG_VERSIONS] },
      configStdin: commands.some((c) => c.name === "fw-apply" && c.options.includes("--config-stdin")),
    },
  };
}

export function registerCapabilitiesCommand(program: Command): void {
  program
    .command("capabilities")
    .description("Describe what this station-cli supports: version, commands and protocol versions")
    .option("--json", "Print the machine-readable document (the only format today; kept for callers that pass it)")
    .action(() => {
      // Walked at run time, when every command is registered.
      logger.log(JSON.stringify(collectCapabilities(program), null, 2));
    });
}
